INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.caveat', 'en', 'This register says where a specification is and what it covers. It is not a validator, and conforming to a published artefact is not the same as being accepted — every platform applies checks that no artefact describes.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.caveat', 'de', 'Dieses Register sagt, wo eine Spezifikation liegt und was sie abdeckt. Es ist kein Prüfdienst: Die Konformität mit einem Artefakt bedeutet nicht Annahme – jede Plattform prüft mehr, als Artefakte beschreiben.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.caveat', 'fr', 'Ce registre indique où se trouve une spécification et ce qu''elle couvre. Ce n''est pas un validateur : être conforme à un artefact publié n''est pas être accepté — chaque plateforme applique des contrôles qu''aucun artefact ne décrit.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.caveat', 'es', 'Este registro indica dónde está una especificación y qué abarca. No es un validador: cumplir un artefacto publicado no equivale a ser aceptado, porque toda plataforma aplica controles que ningún artefacto describe.');
