INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.gateBody', 'en', 'Subscribing is free. The register names the mandated format, its current version, the authoritative file and its licence for twenty jurisdictions — and, for each, what the published artefacts leave out.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.gateBody', 'de', 'Das Abonnement ist kostenlos. Das Register nennt für zwanzig Jurisdiktionen das vorgeschriebene Format, die aktuelle Version, die maßgebliche Datei und deren Lizenz – und was die Artefakte auslassen.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'spec.gateBody', 'fr', 'L''abonnement est gratuit. Le registre indique, pour vingt juridictions, le format imposé, sa version actuelle, le fichier de référence et sa licence — et ce que les artefacts publiés omettent.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
